package org.sleepwell.app;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.widget.*;import java.time.ZoneId;import java.util.*;
/** An original habitual-clock form. No sensors, inferred stages, normative labels or alarm changes. */
public final class HabitualTimingActivity extends Activity {
 private HabitualTiming draft;private HabitualTimingSettings.Factory settings;private String failure="",token,pickerField;private Dialog picker;private Bundle restorePicker;private boolean resumed;private final Handler main=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);settings=HabitualTimingSettings.factory;try{draft=HabitualTimingSettings.read(settings.open(this));if(state!=null){draft.workOnset=state.getInt("workOnset",-1);draft.workEnd=state.getInt("workEnd",-1);draft.freeOnset=state.getInt("freeOnset",-1);draft.freeEnd=state.getInt("freeEnd",-1);draft.workdays=state.getInt("workdays",-1);draft.regular=state.getInt("regular");draft.freeAlarm=state.getInt("freeAlarm");draft.unrestricted=state.getInt("unrestricted");draft.zone=state.getString("zone",draft.zone);draft.revision=state.getLong("revision",draft.revision);failure=state.getString("failure","");token=state.getString("token");pickerField=state.getString("pickerField");restorePicker=state.getBundle("picker");}draft.validate();}catch(RuntimeException error){draft=null;failure=message(error);}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);render();}
 @Override protected void onResume(){super.onResume();resumed=true;observeSave();}@Override protected void onPause(){resumed=false;main.removeCallbacks(poll);super.onPause();}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Self-reported timing",this::back);Design.space(body,12);if(draft==null){Design.text(body,failure,15,500,Design.BROWN);Design.button(body,"Reload saved inputs",true,this::reload);return;}Design.text(body,"Describe a usual week",21,600,Design.INK);Design.text(body,"Use local times when you fall asleep and finally wake, rather than getting into or out of bed.",13,400,Design.MUTED);Design.space(body,14);
  heading(body,"Before workdays");time(body,"workOnset","Sleep onset",draft.workOnset);time(body,"workEnd","Final waking",draft.workEnd);duration(body,draft.workOnset,draft.workEnd);heading(body,"Before free days");time(body,"freeOnset","Sleep onset",draft.freeOnset);time(body,"freeEnd","Final waking",draft.freeEnd);duration(body,draft.freeOnset,draft.freeEnd);
  Design.space(body,8);PlanActivity.detail(body,"calendar","Workdays in a usual week",null,draft.workdays<0?"Not reported":draft.workdays+" of 7",()->choose("workdays"));PlanActivity.detail(body,"clock","Weekly pattern",null,label(draft.regular,"Not reported","Regular day schedule","Night / rotating / irregular"),()->choose("regular"));PlanActivity.detail(body,"bell","Free-day wake alarm","Does an alarm determine final waking?",label(draft.freeAlarm,"Not reported","No","Yes / sometimes"),()->choose("freeAlarm"));PlanActivity.detail(body,"moon","Free-day waking freedom","Consider duties, care or appointments",label(draft.unrestricted,"Not reported","Freely chosen","Constrained"),()->choose("unrestricted"));Design.space(body,12);
  HabitualTiming.Result result=draft.calculate();if(result.available){Design.text(body,"Corrected free-day midpoint",17,600,Design.INK);Design.space(body,5);Design.text(body,PlanActivity.clock(this,HabitualTiming.displayMinute(result.correctedMidpoint)),38,700,Design.INK);Design.text(body,"Self-report timing estimate · rounded to the nearest minute",12,400,Design.MUTED);PlanActivity.detail(body,"clock","Uncorrected free-day midpoint",null,PlanActivity.clock(this,HabitualTiming.displayMinute(result.freeMidpoint)),null);PlanActivity.detail(body,"moon","Weighted weekly duration",null,PlanActivity.duration((int)Math.round(result.weeklyMinutes)),null);PlanActivity.detail(body,"clock","Earlier correction",null,Math.round(result.correction)+" min",null);}else{Design.text(body,"Estimate unavailable",20,600,Design.INK);Design.text(body,result.reason,13,400,Design.MUTED);}Design.space(body,10);Design.text(body,"This describes your reported timing. It does not assign an early/late type, measure body-clock phase or diagnose a condition.",12,400,Design.MUTED);PlanActivity.detail(body,"info","How this is calculated",null,null,this::method);PlanActivity.detail(body,"clock","Reported clock zone","No conversion or dated daylight-saving adjustment",draft.zone,null);Design.button(body,"Use current phone time zone",false,()->{if(token==null){draft.zone=ZoneId.systemDefault().getId();render();}});Design.text(body,"Overnight periods wrap forward once; equal times stay unavailable.",11,400,Design.MUTED);Design.button(body,"Published correction method",false,()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(HabitualTiming.METHOD)));}catch(RuntimeException unavailable){failure="A browser is unavailable. Method DOI: 10.1016/j.cub.2013.04.011";render();}});Design.button(body,"Clear draft inputs",false,()->{if(token==null){long revision=draft.revision;String zone=draft.zone;draft=new HabitualTiming();draft.revision=revision;draft.zone=zone;failure="Draft cleared. Save to replace the saved inputs, or Cancel to keep them.";render();}});
  LinearLayout footer=RecordUi.footer(body);if(!failure.isEmpty()){Design.text(footer,failure,13,500,Design.BROWN);if(token==null)RecordUi.quietButton(footer,"Reload saved inputs",this::reload);}Button save=Design.button(footer,token==null?"Save timing inputs":"Saving…",true,this::save);save.setEnabled(token==null);Design.button(footer,"Cancel changes",false,this::back).setEnabled(token==null);if(token!=null)RecordUi.enabled(body,false);restorePicker();}
 private void heading(LinearLayout body,String title){Design.space(body,8);Design.text(body,title,17,600,Design.INK);}
 private void duration(LinearLayout body,int start,int end){if(start<0||end<0)return;int minutes=HabitualTiming.duration(start,end);Design.text(body,minutes==0?"Equal times are ambiguous.":"Reported period · "+PlanActivity.duration(minutes)+(end<start?" · waking next local day":" · same local day"),12,400,Design.MUTED);}
 private void time(LinearLayout body,String field,String title,int value){PlanActivity.detail(body,"clock",title,null,value<0?"Not reported":PlanActivity.clock(this,value),()->choose(field));}
 private static String label(int selected,String unknown,String yes,String no){return selected==1?yes:selected==2?no:unknown;}
 private void choose(String field){if(token!=null)return;if(picker!=null&&picker.isShowing())return;pickerField=field;int selected;String[] labels;if(field.equals("workdays")){labels=new String[]{"Not reported","0 workdays","1 workday","2 workdays","3 workdays","4 workdays","5 workdays","6 workdays","7 workdays"};selected=draft.workdays+1;picker=SleepPicker.choices(this,"Workdays in a usual week",labels,selected,n->{draft.workdays=n-1;render();});}else if(field.equals("regular")||field.equals("freeAlarm")||field.equals("unrestricted")){if(field.equals("regular")){labels=new String[]{"Not reported","Regular day schedule","Night / rotating / irregular"};selected=draft.regular;}else if(field.equals("freeAlarm")){labels=new String[]{"Not reported","No alarm determines waking","An alarm does / sometimes does"};selected=draft.freeAlarm;}else{labels=new String[]{"Not reported","Waking time is freely chosen","Duties or other constraints apply"};selected=draft.unrestricted;}String title=field.equals("regular")?"Weekly pattern":field.equals("freeAlarm")?"Free-day wake alarm":"Free-day waking freedom";picker=SleepPicker.choices(this,title,labels,selected,n->{if(field.equals("regular"))draft.regular=n;else if(field.equals("freeAlarm"))draft.freeAlarm=n;else draft.unrestricted=n;render();});}else{int value=switch(field){case "workOnset"->draft.workOnset;case "workEnd"->draft.workEnd;case "freeOnset"->draft.freeOnset;case "freeEnd"->draft.freeEnd;default->throw new IllegalArgumentException("Unknown timing field");};String title=switch(field){case "workOnset"->"Workday sleep onset";case "workEnd"->"Workday final waking";case "freeOnset"->"Free-day sleep onset";default->"Free-day final waking";};picker=SleepPicker.time(this,title,value<0?(field.endsWith("Onset")?1380:420):value,n->{switch(field){case "workOnset"->draft.workOnset=n;case "workEnd"->draft.workEnd=n;case "freeOnset"->draft.freeOnset=n;case "freeEnd"->draft.freeEnd=n;default->throw new IllegalArgumentException("Unknown timing field");}render();});}Dialog owned=picker;owned.setOnDismissListener(d->{if(picker==owned){picker=null;pickerField=null;}});}
 private void restorePicker(){if(restorePicker==null||pickerField==null)return;Bundle state=restorePicker;restorePicker=null;String field=pickerField;picker=null;choose(field);if(picker instanceof SleepPicker.StateDialog)picker.onRestoreInstanceState(state);}
 private void method(){if(picker!=null&&picker.isShowing())return;pickerField="method";picker=SleepPicker.message(this,"Published timing method","The weekly duration weights your workday and free-day durations by their reported day counts. The free-day midpoint is advanced by half the excess free-day duration over that weekly average, only when free-day duration is longer than workday duration. Alarm-constrained or otherwise constrained free days, unknown answers and irregular schedules are not scored. These are habitual clock times, not dated DST intervals. This original form is not the licensed MCTQ questionnaire or a validated administration of it.");}
 private void save(){if(token!=null)return;try{draft.validate();failure="";token=UUID.randomUUID().toString();observeSave();render();}catch(RuntimeException invalid){failure=message(invalid);render();}}
 private void observeSave(){if(!resumed||token==null)return;HabitualTiming value=draft.copy();HabitualTimingSettings.Factory pinned=settings;PlanOperations.Operation operation=PlanOperations.start(this,token,app->{HabitualTimingSettings.save(pinned.open(app),value,value.revision);return null;});if(!operation.done){main.removeCallbacks(poll);main.postDelayed(poll,100);return;}PlanOperations.forget(token);token=null;if(operation.error!=null){failure=operation.error;render();return;}draft=HabitualTimingSettings.read(settings.open(this));failure="Timing inputs saved.";render();}
 private final Runnable poll=this::observeSave;private void reload(){if(token!=null)return;try{draft=HabitualTimingSettings.read(settings.open(this));failure="";}catch(RuntimeException error){draft=null;failure=message(error);}render();}private void back(){if(token==null)finish();}
 @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
 @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(draft==null)return;state.putInt("workOnset",draft.workOnset);state.putInt("workEnd",draft.workEnd);state.putInt("freeOnset",draft.freeOnset);state.putInt("freeEnd",draft.freeEnd);state.putInt("workdays",draft.workdays);state.putInt("regular",draft.regular);state.putInt("freeAlarm",draft.freeAlarm);state.putInt("unrestricted",draft.unrestricted);state.putString("zone",draft.zone);state.putLong("revision",draft.revision);state.putString("failure",failure);state.putString("token",token);if(picker instanceof SleepPicker.StateDialog&&!"method".equals(pickerField)){state.putString("pickerField",pickerField);state.putBundle("picker",picker.onSaveInstanceState());}}
 @Override protected void onDestroy(){main.removeCallbacks(poll);if(picker!=null)picker.dismiss();super.onDestroy();}@Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}private static String message(RuntimeException error){return error.getMessage()==null?"Timing inputs are unavailable.":error.getMessage();}
}
